<section class="parents-faq-section"><div class="shell"><div class="parents-section-heading"><h2>Quick answers for parents <span>♡</span></h2></div><div class="parents-faq-grid">${PARENT_FAQS.map(x=>`<article class="faq-item parent-faq-item"><button class="faq-q parent-faq-question" aria-expanded="false"><span>${x[0]}</span><i aria-hidden="true"></i></button><div class="faq-a parent-faq-answer">${x[1]}</div></article>`).join('')}</div></div></section>
