function faq(){const tabs=[['all','start','Getting Started'],['getting','about','About Yani'],['learning','learn','Learning & Activities'],['parents','parents','Parents & Privacy'],['support','support','Setup & Support'],['orders','orders','Orders']];const steps=[['1','Unbox','Say hello to Yani! Everything you need is inside.','unbox','faq-step-unbox-v3.webp'],['2','Connect','Power on Yani and connect to Wi-Fi in minutes.','connect','faq-step-connect-v3.webp'],['3','Create Profile','Add your child’s profile so Yani can personalize their experience.','profile','faq-step-profile-v3.webp'],['4','Meet Yani','Let the fun begin! Yani is ready to learn, play, and grow together.','meet','faq-step-meet-v3.webp']];return`<section class="faq-hero"><div class="faq-hero-scene" role="img" aria-label="Yani peeking from behind a large question mark card"></div><div class="shell faq-hero-inner"><div class="faq-hero-copy"><span class="faq-doodle faq-star-one" aria-hidden="true">☆</span><span class="faq-doodle faq-star-two" aria-hidden="true">✦</span><span class="faq-doodle faq-heart-one" aria-hidden="true">♡</span><span class="faq-doodle faq-heart-two" aria-hidden="true">♡</span><span class="faq-doodle faq-sparkles" aria-hidden="true">✧</span><h1>Questions?<br><span>Yani’s here<br>to help.</span></h1><p>We’ve got answers to the things<br>parents and kids ask most.</p><span class="faq-curl" aria-hidden="true">⌁</span></div><label class="faq-search-wrap" for="faq-search">${faqSearchIcon()}<span class="sr-only">Search frequently asked questions</span><input class="faq-search" id="faq-search" type="search" placeholder="Search for an answer..."></label></div></section>
<section class="faq-main"><div class="shell"><div class="faq-tabs" aria-label="FAQ categories">${tabs.map((x,i)=>`<button class="faq-tab ${i===0?'active':''}" data-faq="${x[0]}" type="button" aria-pressed="${i===0?'true':'false'}">${faqTabIcon(x[1])}<span>${x[2]}</span></button>`).join('')}</div><div class="faq-grid">${FAQS.map(x=>`<article class="faq-item" data-cat="${x[0]}" data-text="${(x[1]+' '+x[2]).toLowerCase()}"><button class="faq-q" type="button" aria-expanded="false"><span>${x[1]}</span><i aria-hidden="true"></i></button><div class="faq-a">${x[2]}</div></article>`).join('')}</div><p class="faq-empty" id="faq-empty" hidden>No answers found. Try another question.</p></div></section>
<section class="faq-steps-section"><div class="shell"><div class="faq-section-heading"><h2>Getting started is easy! <span>♡</span></h2><i class="heading-star left" aria-hidden="true">☆</i><i class="heading-star right" aria-hidden="true">☆</i></div><div class="faq-steps">${steps.map((x,i)=>`<article class="faq-step"><div class="faq-step-copy"><span class="step-number">${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></div><div class="faq-step-art"><img src="${A+x[4]}" alt="${x[1]} Yani setup illustration"></div>${i<steps.length-1?'<span class="step-arrow" aria-hidden="true">→</span>':''}</article>`).join('')}</div></div></section>
<section class="faq-help-section"><div class="shell"><div class="faq-section-heading"><h2>Still need help? <span>♡</span></h2><p>We’re here for you.</p></div><div class="faq-help-cards"><article class="faq-help-card mail"><div class="faq-help-icon">${helpIcon('mail')}</div><div><h3>Email Support</h3><p>Send us a message and we’ll get back to you soon.</p><a href="mailto:contact@brinnoandtech.com">Email Us <svg viewBox="0 0 24 24"><path d="m4 11 16-7-5 16-4-6-7-3Zm7 3 9-10"/></svg></a></div></article><article class="faq-help-card chat"><div class="faq-help-icon">${helpIcon('headset')}</div><div><h3>Talk to the Team</h3><p>Chat with our friendly team during support hours.</p><a href="mailto:contact@brinnoandtech.com?subject=YANI%20Support">Start Chat <svg viewBox="0 0 24 24"><path d="M4 5h16v11H9l-5 4V5Zm5 5h.1m2.9 0h.1m2.9 0h.1"/></svg></a></div></article><article class="faq-help-card guide"><div class="faq-help-icon">${helpIcon('guide')}</div><div><h3>About YANI</h3><p>Download a concise guide to YANI’s planned features, safety direction and prototype status.</p><a href="assets/docs/yani-features-guide.pdf" download="YANI-Features-Guide.pdf">Download PDF <svg viewBox="0 0 24 24"><path d="M12 3v12m-5-5 5 5 5-5M5 20h14"/></svg></a></div></article></div></div></section>
<section class="faq-adventure"><div class="shell faq-adventure-panel"><div class="faq-adventure-copy"><h2>Ready for your next adventure?</h2><p>Let’s learn, play, and imagine together!</p><a href="${JOIN_URL}" target="_blank" rel="noopener noreferrer">Join the waitlist ${cartIcon()}</a></div></div></section>
<section class="faq-gift-cta" id="early-access"><div class="shell faq-gift-panel"><div class="faq-gift-art"><img src="${A}newsletter-gift-v2.webp" alt="Yellow gift box wrapped with a purple bow"><span>☆</span><i>⌁</i></div><h2>Give your child a friend who learns, cares,<br>and grows with them.</h2><a href="${JOIN_URL}" target="_blank" rel="noopener noreferrer">Join the waitlist ${cartIcon()}</a></div></section>`}

const templates={home,about,features,parents,kids,gallery,faq};
const assistantIcon=()=>`<svg viewBox="0 0 32 32" aria-hidden="true"><path d="M6 7h20a3 3 0 0 1 3 3v12a3 3 0 0 1-3 3H15l-7 5 1-5H6a3 3 0 0 1-3-3V10a3 3 0 0 1 3-3Z"/><path d="M9 16h.1M16 16h.1M23 16h.1"/></svg>`;
const assistantKnowledge=[
  {matches:['hello','hi','hey','good morning','good afternoon','good evening'],response:'Hello! I’m the YANI Product Guide. I can help you learn about BR Innovation & Technology, YANI’s capabilities, family features, early access and ways to contact our team.'},
  {matches:['contact','email','phone','location','address','reach','social'],response:'You can reach BR Innovation & Technology at +91 7975515056, contact@brinnoandtech.com or info@brinnoandtech.com. We are based in Bangalore, Karnataka, India.'},
  {matches:['price','pricing','cost','buy','purchase','waitlist','join','available'],response:'YANI is currently in development and prototype testing, so final pricing and availability have not been announced. You can use any “Join the waitlist” button for progress updates and future testing opportunities.'},
  {matches:['parent','privacy','safe','safety','control'],response:'YANI’s prototype is being developed with family-first safeguards in mind. Parent controls, protected pairing, child-aware experiences and privacy choices are part of the current testing and validation work—not finished product claims.'},
  {matches:['feature','capabilit','what can','solution','service','offer'],response:'The YANI prototype is exploring adaptive learning, natural conversations, stories and games, daily routines, emotion-aware support and parent controls. These capabilities are still being developed and validated through supervised testing.'},
  {matches:['learn','school','education','quiz','story'],response:'YANI’s learning experience is being designed around age-aware conversations, stories, quizzes and guided activities. The team is testing how well the prototype can adapt to a child’s pace and interests with parent guidance.'},
  {matches:['founder','bindu','leadership','who leads'],response:'BR Innovation & Technology is led by founder and partner Bindu R, who is guiding YANI toward accessible learning experiences for homes and schools across India.'},
  {matches:['br innovation','company','about br','who are you','startup'],response:'BR Innovation & Technology is a Bangalore-based AI educational robotics company founded in 2025. We are developing YANI, our flagship prototype, through an iterative testing and validation process.'},
  {matches:['what is yani','about yani','yani','robot','companion','product'],response:'YANI is BR Innovation & Technology’s flagship adaptive AI companion prototype for children ages 3–13. It is currently in development and supervised testing. We’re designing it to support age-aware learning, natural conversation and emotional engagement—with parent guidance and safety checks shaping every stage.'}
];
function header(){document.getElementById('site-header').innerHTML=`<header class="site-header"><div class="shell nav"><a class="logo company-brand" href="index.html" aria-label="BR Innovation & Technology home"><img src="${A}br-innovation-logo-512.png" alt=""><span class="company-brand-copy"><strong>BR Innovation</strong><small>&amp; Technology</small></span></a><nav class="nav-links" id="nav-links">${NAV.map(x=>`<a class="${PAGE===x[0]?'active':''}" href="${x[2]}">${x[1]}</a>`).join('')}</nav><a class="preorder top-waitlist" href="${JOIN_URL}" target="_blank" rel="noopener noreferrer">Join the waitlist ${cartIcon()}</a><button class="menu-btn" aria-label="Open menu"><i></i><i></i><i></i></button></div></header>`}
function footer(){document.getElementById('site-footer').innerHTML=`<footer class="site-footer"><div class="shell footer-shell"><div class="footer-grid">
  <section class="footer-about" aria-label="About BR Innovation & Technology"><a class="footer-company-brand" href="index.html"><img src="${A}br-innovation-logo-512.png" alt=""><span><strong>BR Innovation</strong><small>&amp; Technology</small></span></a><p>Building thoughtful AI and educational robotics that help children learn, feel and grow—with YANI as our flagship companion.</p><div class="footer-socials" aria-label="Social links"><a href="https://www.linkedin.com/company/br-innovation-and-technology/" target="_blank" rel="noopener noreferrer" aria-label="BR Innovation & Technology on LinkedIn">in</a><a href="https://www.instagram.com/brinnovationandtechnology?igsh=aGExMDNpMHMxOXZx" target="_blank" rel="noopener noreferrer" aria-label="BR Innovation & Technology on Instagram"><span class="instagram-mark"></span></a></div></section>
  <nav class="footer-column" aria-label="Product links"><h3>YANI</h3><a href="features.html">Product Features</a><a href="kids.html">For Kids</a><a href="parents.html">For Parents</a><a href="gallery.html">Gallery</a></nav>
  <nav class="footer-column" aria-label="Company links"><h3>Company</h3><a href="about.html">About Us</a><a href="about.html#journey-title">Our Journey</a><a href="about.html">Leadership</a><button type="button" class="footer-chat-link" data-assistant-open aria-controls="yani-assistant">Talk to YANI</button></nav>
  <section class="footer-column footer-contact" aria-label="Contact information"><h3>Contact</h3><span>Bangalore, Karnataka, India</span><a href="tel:+917975515056">+91 7975515056</a><a href="mailto:contact@brinnoandtech.com">contact@brinnoandtech.com</a><a href="mailto:info@brinnoandtech.com">info@brinnoandtech.com</a></section>
  <section class="footer-connect"><h3>Stay Connected</h3><p>Join our community for product news, learning ideas and YANI updates.</p><a class="footer-form footer-waitlist" href="${JOIN_URL}" target="_blank" rel="noopener noreferrer"><span>Join the waitlist</span><svg viewBox="0 0 32 32" aria-hidden="true"><path d="m4 15 24-10-8 22-5-9-11-3Zm11 3L28 5"/></svg></a></section>
  </div><div class="copyright"><span>© 2026 BR Innovation &amp; Technology. All rights reserved.</span><span class="footer-legal"><a href="privacy.html">Privacy</a><a href="terms.html">Terms</a></span></div></div></footer>`}
function assistant(){document.body.insertAdjacentHTML('beforeend',`<button class="assistant-fab" type="button" data-assistant-open aria-controls="yani-assistant" aria-expanded="false"><span class="assistant-fab-avatar"><img src="${A}yani-happy.webp" alt=""></span><span><small>Need help?</small><strong>Talk to YANI</strong></span>${assistantIcon()}</button><aside class="yani-assistant" id="yani-assistant" role="dialog" aria-labelledby="assistant-title" hidden><header class="assistant-header"><div class="assistant-avatar"><img src="${A}yani-happy.webp" alt="YANI"></div><div><h2 id="assistant-title">YANI Product Guide</h2><p><span></span> BR Innovation virtual assistant</p></div><button type="button" class="assistant-close" aria-label="Close YANI assistant">×</button></header><div class="assistant-messages" id="assistant-messages" aria-live="polite"><div class="assistant-message bot"><span class="assistant-message-avatar"><img src="${A}yani-happy.webp" alt=""></span><div class="assistant-message-body"><strong>YANI</strong><p>Hi! I’m YANI’s virtual product guide.</p><small>Ask me about our company, the prototype, learning features, safety or early access.</small></div></div></div><div class="assistant-quick" aria-label="Suggested questions"><button type="button">What is YANI?</button><button type="button">What can YANI do?</button><button type="button">Is YANI safe?</button><button type="button">Contact the team</button></div><form class="assistant-form" autocomplete="off"><label class="sr-only" for="assistant-input">Ask YANI a question</label><input id="assistant-input" type="text" autocomplete="off" maxlength="240" placeholder="Message YANI…"><button type="submit" aria-label="Send message">${assistantIcon()}</button></form><p class="assistant-disclaimer">Virtual guide • YANI is currently in prototype testing</p></aside>`)}
function assistantReply(input){const value=input.toLowerCase().trim();const match=assistantKnowledge.find(item=>item.matches.some(keyword=>value.includes(keyword)));return match?.response||'I can help with BR Innovation & Technology, YANI’s features, learning, family safety, early access and contact details. Try one of the suggested questions, or email contact@brinnoandtech.com for a detailed inquiry.'}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),2600)}
function interactions(){const mb=document.querySelector('.menu-btn'),nav=document.querySelector('.nav-links');const closeMenu=()=>{nav.classList.remove('open');document.body.classList.remove('menu-open');mb.setAttribute('aria-expanded','false')};mb.setAttribute('aria-expanded','false');mb.setAttribute('aria-controls','nav-links');mb.onclick=()=>{const open=!nav.classList.contains('open');nav.classList.toggle('open',open);document.body.classList.toggle('menu-open',open);mb.setAttribute('aria-expanded',String(open));mb.setAttribute('aria-label',open?'Close menu':'Open menu')};nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){closeMenu();mb.focus()}});document.querySelectorAll('.interest-form').forEach(f=>f.onsubmit=e=>{e.preventDefault();if(f.reportValidity()){toast('Thanks! You are on Yani’s early-access list.');f.reset()}});document.querySelectorAll('.faq-q').forEach(q=>q.onclick=()=>{const item=q.closest('.faq-item');item.classList.toggle('open');q.setAttribute('aria-expanded',item.classList.contains('open'))});let cat='all';const search=document.getElementById('faq-search'),empty=document.getElementById('faq-empty');function applyFaq(){const s=(search?.value||'').trim().toLowerCase();let visible=0;document.querySelectorAll('.faq-item').forEach(i=>{const hide=(cat!=='all'&&i.dataset.cat!==cat)||(s&&!i.dataset.text.includes(s));i.classList.toggle('hide',hide);if(!hide)visible++});if(empty)empty.hidden=visible!==0}search?.addEventListener('input',applyFaq);document.querySelectorAll('.faq-tab').forEach(b=>b.onclick=()=>{cat=b.dataset.faq;document.querySelectorAll('.faq-tab').forEach(x=>{x.classList.remove('active');x.setAttribute('aria-pressed','false')});b.classList.add('active');b.setAttribute('aria-pressed','true');applyFaq()});document.querySelectorAll('.gallery-filter').forEach(b=>b.onclick=()=>{const c=b.dataset.gallery;document.querySelectorAll('.gallery-filter').forEach(x=>{x.classList.remove('active');x.setAttribute('aria-pressed','false')});b.classList.add('active');b.setAttribute('aria-pressed','true');document.querySelectorAll('.gallery-story').forEach(i=>i.classList.toggle('is-hidden',c!=='all'&&!i.dataset.cats.split(' ').includes(c)))});const labTrack=document.querySelector('.gallery-lab-track');document.querySelector('.gallery-lab-prev')?.addEventListener('click',()=>labTrack.scrollBy({left:-labTrack.clientWidth*.68,behavior:'smooth'}));document.querySelector('.gallery-lab-next')?.addEventListener('click',()=>labTrack.scrollBy({left:labTrack.clientWidth*.68,behavior:'smooth'}))}
function assistantInteractions(){const panel=document.getElementById('yani-assistant'),messages=document.getElementById('assistant-messages'),input=document.getElementById('assistant-input'),form=document.querySelector('.assistant-form'),close=document.querySelector('.assistant-close'),launchers=document.querySelectorAll('[data-assistant-open]');const setOpen=open=>{panel.hidden=!open;launchers.forEach(button=>button.setAttribute('aria-expanded',String(open)));document.body.classList.toggle('assistant-open',open);if(open)setTimeout(()=>input.focus(),60)};launchers.forEach(button=>button.addEventListener('click',()=>setOpen(true)));close.addEventListener('click',()=>setOpen(false));const addAvatar=item=>{const avatar=document.createElement('span');avatar.className='assistant-message-avatar';const image=document.createElement('img');image.src=`${A}yani-happy.webp`;image.alt='';avatar.appendChild(image);item.appendChild(avatar)};const addMessage=(copy,type,detail='')=>{const item=document.createElement('div');item.className=`assistant-message ${type}`;const bot=type.split(' ').includes('bot');if(bot)addAvatar(item);const body=document.createElement('div');body.className='assistant-message-body';if(bot){const author=document.createElement('strong');author.textContent='YANI';body.appendChild(author)}const text=document.createElement('p');text.textContent=copy;body.appendChild(text);if(detail){const small=document.createElement('small');small.textContent=detail;body.appendChild(small)}item.appendChild(body);messages.appendChild(item);messages.scrollTop=messages.scrollHeight;return item};const addTyping=()=>{const item=document.createElement('div');item.className='assistant-message bot typing';item.setAttribute('role','status');item.setAttribute('aria-label','YANI is typing');addAvatar(item);const body=document.createElement('div');body.className='assistant-message-body';const author=document.createElement('strong');author.textContent='YANI';const status=document.createElement('div');status.className='typing-status';const label=document.createElement('span');label.className='typing-label';label.textContent='Typing';const dots=document.createElement('span');dots.className='typing-dots';dots.setAttribute('aria-hidden','true');for(let i=0;i<3;i++)dots.appendChild(document.createElement('i'));status.append(label,dots);body.append(author,status);item.appendChild(body);messages.appendChild(item);messages.scrollTop=messages.scrollHeight;return item};const send=question=>{const value=question.trim();if(!value)return;addMessage(value,'user');input.value='';const typing=addTyping();setTimeout(()=>{typing.remove();addMessage(assistantReply(value),'bot')},780)};form.addEventListener('submit',event=>{event.preventDefault();send(input.value)});document.querySelectorAll('.assistant-quick button').forEach(button=>button.addEventListener('click',()=>send(button.textContent)));document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!panel.hidden){setOpen(false);document.querySelector('.assistant-fab').focus()}})}
function structuredData(){
  const meta=PAGE_META[PAGE];
  if(!meta)return;
  const organization={
    '@type':'Organization','@id':`${SITE_URL}#organization`,name:'BR Innovation & Technology',url:SITE_URL,
    logo:{'@type':'ImageObject',url:`${SITE_URL}${A}br-innovation-logo-512.png`,width:512,height:512},
    description:'A Bangalore-based AI educational robotics company developing YANI, an adaptive learning companion prototype for children and families.',
    foundingDate:'2025',telephone:'+91 7975515056',email:'contact@brinnoandtech.com',
    address:{'@type':'PostalAddress',addressLocality:'Bangalore',addressRegion:'Karnataka',addressCountry:'IN'},
    sameAs:['https://www.linkedin.com/company/br-innovation-and-technology/','https://www.instagram.com/brinnovationandtechnology/']
  };
  const url=`${SITE_URL}${meta.path}`;
  const graph=[organization,{'@type':meta.type,'@id':`${url}#webpage`,url,name:meta.name,description:meta.description,isPartOf:{'@id':`${SITE_URL}#website`},about:{'@id':`${SITE_URL}#organization`},inLanguage:'en-IN'}];
  if(PAGE==='home')graph.push({'@type':'WebSite','@id':`${SITE_URL}#website`,url:SITE_URL,name:'BR Innovation & Technology',publisher:{'@id':`${SITE_URL}#organization`},inLanguage:'en-IN'});
  if(PAGE==='features')graph.push({'@type':'Product','@id':`${url}#yani`,name:'YANI',url,description:'An adaptive AI learning companion prototype for children ages 3–13, currently in development and supervised testing.',brand:{'@id':`${SITE_URL}#organization`},category:'Educational robot prototype',audience:{'@type':'PeopleAudience',suggestedMinAge:3,suggestedMaxAge:13},additionalProperty:{'@type':'PropertyValue',name:'Development status',value:'Prototype testing'}});
  if(PAGE==='faq')graph.push({'@type':'FAQPage','@id':`${url}#faq`,mainEntity:FAQS.map(item=>({'@type':'Question',name:item[1],acceptedAnswer:{'@type':'Answer',text:item[2]}}))});
  if(PAGE!=='home')graph.push({'@type':'BreadcrumbList','@id':`${url}#breadcrumb`,itemListElement:[{'@type':'ListItem',position:1,name:'Home',item:SITE_URL},{'@type':'ListItem',position:2,name:meta.name,item:url}]});
  const script=document.createElement('script');script.id='structured-data';script.type='application/ld+json';script.textContent=JSON.stringify({'@context':'https://schema.org','@graph':graph});document.head.appendChild(script);
}
function optimizeMedia(){document.querySelectorAll('main img').forEach((image,index)=>{if(!image.hasAttribute('loading'))image.loading=index===0?'eager':'lazy';image.decoding='async';if(index===0)image.fetchPriority='high'});document.querySelectorAll('video').forEach(video=>{video.preload='metadata';video.playsInline=true})}
const main=document.getElementById('main-content');
if(!document.querySelector('.site-header'))header();
if(!main.children.length)main.innerHTML=(templates[PAGE]||home)();
if(!document.querySelector('.site-footer'))footer();
if(!document.getElementById('yani-assistant'))assistant();
structuredData();optimizeMedia();interactions();assistantInteractions();
